'use client';

import { Mindmap } from '@diax/react';
import {
  Box,
  Cloud,
  Code,
  Database,
  type LucideIcon,
  Monitor,
  Server,
  Shield,
} from 'lucide-react';

const RadarNode = ({
  icon: Icon,
  title,
  ring,
}: {
  icon: LucideIcon;
  title: string;
  ring: 'adopt' | 'trial' | 'assess' | 'hold' | 'hub';
}) => {
  const styles = {
    hub: 'border-[#5E6AD2]/50 bg-[#5E6AD2]/15 text-white shadow-[0_0_20px_rgba(94,106,210,0.3)] min-w-[140px] justify-center',
    adopt: 'border-emerald-500/40 bg-emerald-500/10 text-emerald-300',
    trial: 'border-sky-500/40 bg-sky-500/10 text-sky-300',
    assess: 'border-amber-500/40 bg-amber-500/10 text-amber-300',
    hold: 'border-red-400/30 bg-red-400/5 text-red-300/70',
  };

  return (
    <div
      className={`flex items-center gap-2.5 rounded-xl border px-4 py-2.5 backdrop-blur-md shadow-lg transition-all ${styles[ring]}`}
    >
      <Icon className="h-4 w-4 shrink-0" />
      <span className="text-sm font-medium whitespace-nowrap">{title}</span>
    </div>
  );
};

export default function TechRadar() {
  return (
    <Mindmap
      nodes={[
        {
          id: 'hub',
          content: <RadarNode icon={Box} title="Tech Radar 2025" ring="hub" />,
        },
        {
          id: 'frontend',
          content: <RadarNode icon={Monitor} title="React 19" ring="adopt" />,
        },
        {
          id: 'lang',
          content: <RadarNode icon={Code} title="TypeScript" ring="adopt" />,
        },
        {
          id: 'infra',
          content: <RadarNode icon={Cloud} title="Vercel Edge" ring="trial" />,
        },
        {
          id: 'db',
          content: (
            <RadarNode icon={Database} title="Turso SQLite" ring="assess" />
          ),
        },
        {
          id: 'backend',
          content: <RadarNode icon={Server} title="tRPC" ring="adopt" />,
        },
        {
          id: 'auth',
          content: <RadarNode icon={Shield} title="Passkeys" ring="trial" />,
        },
      ]}
      relations={[
        'hub->frontend',
        'hub->lang',
        'hub->infra',
        'hub->db',
        'hub->backend',
        'hub->auth',
      ]}
      density="comfortable"
      stagger
      highlightOnHover
    />
  );
}
